shellCommands.command:
(npx next start -p 3123 > /tmp/next-start.log 2>&1 &) && sleep 4 && for u in / /blog /blog/1 /blog/999 /nonexistent /api/posts "/api/posts/7"; do printf '%-16s -> %s
' "$u" "$(curl -s -o /dev/null -w '%{http_code}' http://localhost:3123$u)"; done; echo; echo "--- title tags:"; for u in / /blog /blog/1 /nonexistent; do curl -s http://localhost:3123$u | grep -o '<title>[^<]*</title>' | head -1; done; echo; echo "--- head of / (font + og + description):"; curl -s http://localhost:3123/ | grep -o '<meta[^>]*\(description\|og:title\)[^>]*>\|<link[^>]*font[^>]*>' | head; echo; echo "--- body content check:"; curl -s http://localhost:3123/ | grep -o 'Your user agent: [^<]*\|href="/blog/[0-9]*"' | head -3; curl -s http://localhost:3123/blog/1 | grep -o 'Comments ([0-9]*)\|← Back'; echo; echo "--- API:"; curl -s http://localhost:3123/api/posts; echo; curl -s -X POST -H 'content-type: application/json' -d '{"title":"T"}' -w ' [%{http_code}]' http://localhost:3123/api/posts; echo; curl -s -X POST -H 'content-type: application/json' -d '{"title":"T","content":"C"}' -w ' [%{http_code}]' http://localhost:3123/api/posts; echo; curl -s -X PUT -H 'content-type: application/json' -d '{"title":"New"}' http://localhost:3123/api/posts/7; echo; curl -s -X DELETE http://localhost:3123/api/posts/7; echo; curl -s -X PATCH -o /dev/null -w 'PATCH /api/posts/7 -> %{http_code} allow=%header{allow}
' http://localhost:3123/api/posts/7; curl -s -X DELETE -o /dev/null -w 'DELETE /api/posts -> %{http_code} allow=%header{allow}
' http://localhost:3123/api/posts; pkill -f 'next start' ; true
